end local connection=RunService.RenderStepped:Connect(function()if not running then return end for _,data in pairs(particles)do data.X=data.X+data.SpeedX data.Y=data.Y+data.SpeedY local float=math.sin(tick()*0.5+data.FloatOffset)*0.002 data.X=data.X+float if data.Y>1.2 then data.X=math.random()*0.95+0.025 data.Y=-0.15 data.SpeedX=(math.random()-0.5)*0.003 data.SpeedY=0.0008+math.random()*0.004 data.RotSpeed=(math.random()-0.5)*0.008 data.Object.TextColor3=Color3.fromRGB(100+math.random()*155,220+math.random()*35,255)data.Object.TextSize=8+math.random()*14 data.Object.Text=symbols[math.random(1,#symbols)]end data.Object.Position=UDim2.new(math.clamp(data.X,0,1),0,math.clamp(data.Y,-0.1,1.2),0)data.Object.Rotation=data.Object.Rotation+data.RotSpeed local alpha=0.1+(data.Y+0.15)/1.35*0.6 data.Object.TextTransparency=math.clamp(0.5-alpha*0.5,0.1,0.6)end end)return{Stop=function()running=false connection:Disconnect()end,Container=container}end local CONFIGS={FOV_IV=250,LATENCY_IV=100,RAPID_FIRE=80,KILL_AURA_RADIUS=50,KILL_AURA_DAMAGE=50,IGNORE_TEAMMATES=true,NETWORK_LATENCY_FACTOR=0.22,HITBOX_LEVEL=15,PREDICTION_TIME=220}local LockConfig={Enabled=false,AimPart="HumanoidRootPart",FOV=150,MaxDistance=400,LockSpeed=1.0,Stickiness=1.0,HoldTime=1.5,TeamCheck=true,WallCheck=false,UseRightClick=true,ShowFOV=false,FOVColor=CYAN,PredictionX=0.15,PredictionY=0.10,PredictionEnabled=false}local currentTarget=nil local targetPart=nil local targetLostTime=0 local targetPosition=nil local fovCircle=nil local fovCircleInner=nil local lockRunning=false local lockLoop=nil local lockHUD=nil local lockHUDLoop=nil local lockHUDPosLoop=nil local function GenerateSCID()local chars="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"local function randStr(len)local s=""for i=1,len do local idx=math.random(1,#chars)s=s..string.sub(chars,idx,idx)end return s end local scid="SCID X1Z:"..randStr(3)..":"..randStr(3)return scid end local SCID_VALUE=GenerateSCID()local function GetPredictedPosition(targetChar,aimPart)if not targetChar or not aimPart then return aimPart and aimPart.Position or Vector3.new()end if not LockConfig.PredictionEnabled then return aimPart.Position end local velocity=aimPart.AssemblyLinearVelocity or Vector3.new()local basePos=aimPart.Position local predX=velocity.X*LockConfig.PredictionX local predY=velocity.Y*LockConfig.PredictionY local predZ=velocity.Z*LockConfig.PredictionX return basePos+Vector3.new(predX,predY,predZ)end local function FindBestTarget()local character=player.Character if not character or not character.PrimaryPart then return nil,nil end local viewportX=Camera.ViewportSize.X/2 local viewportY=Camera.ViewportSize.Y/2 local bestTarget=nil local bestPart=nil local bestDist=LockConfig.FOV+1 for _,plr in pairs(Players:GetPlayers())do if plr==player then continue end if LockConfig.TeamCheck then if plr.Team and player.Team then if plr.Team==player.Team then continue end end end local targetChar=plr.Character if not targetChar then continue end local aimPart=targetChar:FindFirstChild("HumanoidRootPart")if not aimPart then aimPart=targetChar:FindFirstChild("UpperTorso")end if not aimPart then aimPart=targetChar:FindFirstChild("Torso")end if not aimPart then aimPart=targetChar:FindFirstChild("Head")end if not aimPart then aimPart=targetChar.PrimaryPart end if not aimPart then continue end local humanoid=targetChar:FindFirstChild("Humanoid")if humanoid and humanoid.Health<=0 then continue end local distance=(character.PrimaryPart.Position-aimPart.Position).Magnitude if distance>LockConfig.MaxDistance then continue end if LockConfig.WallCheck then local ray=Ray.new(character.PrimaryPart.Position,(aimPart.Position-character.PrimaryPart.Position).Unit*1000)local hit=Workspace:FindPartOnRay(ray,character)if hit and not hit:IsDescendantOf(targetChar)then continue end end local targetPos=GetPredictedPosition(targetChar,aimPart)local screenPos,onScreen=Camera:WorldToScreenPoint(targetPos)if not onScreen then continue end local distToCenter=math.sqrt((screenPos.X-viewportX)^2+(screenPos.Y-viewportY)^2)if distToCenter<=LockConfig.FOV and distToCenter<bestDist then bestDist=distToCenter bestTarget=plr bestPart=aimPart end end return bestTarget,bestPart end local function IsTargetValid(target,part)if not target or not part then return false end if not target.Character then return false end if not part.Parent then return false end local humanoid=target.Character:FindFirstChild("Humanoid")if humanoid and humanoid.Health<=0 then return false end local character=player.Character if character and character.PrimaryPart then local distance=(character.PrimaryPart.Position-part.Position).Magnitude if distance>LockConfig.MaxDistance then return false end end local targetPos=GetPredictedPosition(target.Character,part)local screenPos,onScreen=Camera:WorldToScreenPoint(targetPos)if not onScreen then return false end local viewportX=Camera.ViewportSize.X/2 local viewportY=Camera.ViewportSize.Y/2 local distToCenter=math.sqrt((screenPos.X-viewportX)^2+(screenPos.Y-viewportY)^2)local stickyFOV=LockConfig.FOV*(1+LockConfig.Stickiness*0.5)return distToCenter<=stickyFOV end local function CreateLockHUD()local screenGui=Instance.new("ScreenGui")screenGui.Name="LockHUD"screenGui.Parent=player:WaitForChild("PlayerGui")local mainFrame=Instance.new("Frame")mainFrame.Name="MainFrame"mainFrame.Size=UDim2.new(0,80,0,8)mainFrame.Position=UDim2.new(0.5,-40,0.5,25)mainFrame.BackgroundTransparency=1 mainFrame.Parent=screenGui local barBackground=Instance.new("Frame")barBackground.Name="BarBackground"barBackground.Size=UDim2.new(1,0,1,0)barBackground.BackgroundColor3=Color3.new(0,0.15,0.15)barBackground.BackgroundTransparency=0.4 barBackground.BorderSizePixel=0 barBackground.ClipsDescendants=true barBackground.Parent=mainFrame local cornerBg=Instance.new("UICorner")cornerBg.CornerRadius=UDim.new(0,4)cornerBg.Parent=barBackground local statusBar=Instance.new("Frame")statusBar.Name="StatusBar"statusBar.Size=UDim2.new(0,0,1,0)statusBar.BackgroundC