DescendantsInstances={player.Character,camera}local result=Workspace:Raycast(camera.CFrame.Position,hrp.Position-camera.CFrame.Position,raycastParams)if not result then return true end return result.Instance and result.Instance:IsDescendantOf(enemyCharacter)end local function GetEnemyHealth(character)local humanoid=character:FindFirstChild("Humanoid")if humanoid then return humanoid.Health,humanoid.MaxHealth end return 0,100 end local function GetEnemyDistance(character)if not player.Character then return 0 end local hrp=player.Character:FindFirstChild("HumanoidRootPart")if not hrp then return 0 end local targetHrp=character:FindFirstChild("HumanoidRootPart")if not targetHrp then return 0 end return math.floor((hrp.Position-targetHrp.Position).Magnitude+0.5)end local enemyLastPositions={}local enemyLastUpdateTime={}local enemySpeedHistory={}local function GetDeltaTime(userId)local now=os.clock()local lastTime=enemyLastUpdateTime[userId]or now local dt=now-lastTime enemyLastUpdateTime[userId]=now return math.max(dt,0.001)end local function GetEnemySpeed(character)local hrp=character:FindFirstChild("HumanoidRootPart")if not hrp then return 0 end local currentPos=hrp.Position local userId=Players:GetPlayerFromCharacter(character)if not userId then return 0 end if enemyLastPositions[userId]then local lastPos=enemyLastPositions[userId]local deltaPos=currentPos-lastPos local deltaTime=GetDeltaTime(userId)local speed=deltaPos.Magnitude/deltaTime enemyLastPositions[userId]=currentPos if not enemySpeedHistory[userId]then enemySpeedHistory[userId]={}end table.insert(enemySpeedHistory[userId],speed)if #enemySpeedHistory[userId]>5 then table.remove(enemySpeedHistory[userId],1)end local avgSpeed=0 local weightSum=0 for i,v in ipairs(enemySpeedHistory[userId])do local weight=i/#enemySpeedHistory[userId]avgSpeed=avgSpeed+v*weight weightSum=weightSum+weight end avgSpeed=avgSpeed/weightSum avgSpeed=avgSpeed*1.4 return math.floor(avgSpeed+0.5)end enemyLastPositions[userId]=currentPos return 0 end local function UpdateLockHUD(hud)if not hud then return end local mousePos=UserInputService:GetMouseLocation()local viewportSize=Camera.ViewportSize local xPos=math.clamp(mousePos.X/viewportSize.X,0,1)local yPos=math.clamp(mousePos.Y/viewportSize.Y+0.045,0,1)hud.MainFrame.Position=UDim2.new(xPos,-40,yPos,0)if not currentTarget or not targetPart then hud.InfoFrame.Visible=false hud.DistanceText.Text=""hud.StatusBar.BackgroundColor3=DEEP_CYAN hud.StatusBar.Size=UDim2.new(0,0,1,0)hud.StatusText.Text="○"hud.StatusText.TextColor3=DEEP_CYAN hud.BarBackground.BackgroundColor3=Color3.new(0,0.1,0.1)return end local targetChar=currentTarget.Character if not targetChar then hud.InfoFrame.Visible=false hud.DistanceText.Text=""return end local humanoid=targetChar:FindFirstChild("Humanoid")local isDead=not humanoid or humanoid.Health<=0 local health,maxHealth=GetEnemyHealth(targetChar)local healthPercent=math.floor((health/maxHealth)*100)local name=currentTarget.DisplayName or currentTarget.Name local healthColor=GetHealthColor(healthPercent)local distance=GetEnemyDistance(targetChar)local visible=IsEnemyVisible(targetChar)local speed=GetEnemySpeed(targetChar)local speedColor=GetSpeedColor(speed)local viewportX=Camera.ViewportSize.X/2 local viewportY=Camera.ViewportSize.Y/2 local screenPos,onScreen=Camera:WorldToScreenPoint(targetPart.Position)local enemyDistance=0 if onScreen then enemyDistance=math.sqrt((screenPos.X-viewportX)^2+(screenPos.Y-viewportY)^2)end local fillPercentage=math.clamp(1-(enemyDistance/LockConfig.FOV),0,1)hud.InfoFrame.Visible=true if isDead then hud.NameText.Text="☠️ "..name hud.DistanceText.Text=""hud.HealthBar.Size=UDim2.new(0,0,1,0)hud.HealthText.Text="💀"hud.HealthText.TextColor3=Color3.new(1,0,0)hud.HealthBarBg.BackgroundColor3=Color3.new(0.3,0,0)else hud.NameText.Text="🎯 "..name hud.DistanceText.Text="📏 "..distance.."m  |  ☄️ "..speed hud.DistanceText.TextColor3=speedColor hud.HealthBar.Size=UDim2.new(healthPercent/100,0,1,0)hud.HealthBa